\n    \"/app/resources/treasury_bulletin_1975_03_page_36.txt\",\n    \"/app/resources/treasury_bulletin_1976_03_page_38.txt\"\n]\n\nfor f in files:\n    print(f\"\\n{'='*60}\")\n    print(f\"File: {f}\")\n    with open(f, 'r') as file:\n        content = file.read()\n    \n    # Let's find all the \"Total\" rows and their associated year\n    # Looking for pattern like \"<tr><td>1972</td>...<td>Total</td>\"\n    # or direct year totals\n    \n    # First let's look for year labels with Total values\n    # The structure is that years appear as headers and Total rows follow\n    lines = content.split('\\n')\n    for i, line in enumerate(lines):\n        if 'Total' in line and ('1972' in line or '1973' in line or '1974' in line or \n                                '1975' in line or '1976' in line or '1977' in line or \n                                '1978' in line or '1979' in line or '1980' in line):\n            # Print context\n            start = max(0, i-2)\n            end = min(len(lines), i+3)\n            print(f\"\\nLine {i}: {lines[i][:100]}\")\n            for j in range(start, end):\n                print(f\"  {j}: {lines[j][:120]}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
